import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track opponent behavior, with extra weight on recent rounds.
    opp_c = 0
    opp_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    streak_opp = history[-1][1]
    streak_len = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == streak_opp:
            streak_len += 1
        else:
            break
    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'C' and b == 'D':
            cd += 1
        elif a == 'D' and b == 'C':
            dc += 1
        else:
            dd += 1

    rounds_left = 100 - n
    last_my, last_op = history[-1]

    recent_n = min(8, n)
    recent_opp_d = 0
    recent_my_d = 0
    for i in range(n - recent_n, n):
        if history[i][1] == 'D':
            recent_opp_d += 1
        if history[i][0] == 'D':
            recent_my_d += 1

    # Endgame: squeeze cooperators, defect against non-cooperators.
    if rounds_left <= 1:
        return 'D'
    if rounds_left <= 3:
        if opp_c > 0 and opp_d == 0 and n >= 15:
            return 'D'
        if opp_d * 3 <= n:
            return 'D'
        if opp_d * 5 >= n * 4:
            return 'D'
        return 'D'

    # Very short history: build trust but don't get punked by an opener D.
    if n <= 3:
        if last_op == 'D':
            return 'D'
        return 'C'

    opp_rate = opp_c / n

    # Extremely cooperative opponent: milk them, don't get stuck in CC.
    if opp_rate >= 0.9 and n >= 8:
        # Punish the occasional betrayal, otherwise defect often in midgame.
        if last_op == 'D':
            return 'D'
        if rounds_left <= 6:
            return 'D'
        # Probe early to confirm they are unconditional, then exploit.
        if n < 12:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Mostly defecting opponent: defect back; rare probe when they reciprocate.
    if opp_rate <= 0.15:
        if last_op == 'C':
            return 'C'
        if rounds_left <= 12:
            return 'D'
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # If opponent has defected a lot in recent rounds, defect.
    if recent_opp_d >= 4 and recent_n >= 5:
        return 'D'

    # Long opponent D streak: retaliate, but break free if they change.
    if streak_opp == 'D' and streak_len >= 3:
        if streak_len >= 6:
            # Try to reset with a cooperative probe rarely.
            if rng.random() < 0.1:
                return 'C'
        return 'D'

    # Forgiving TFT core: respond to last action, with forgiveness when
    # opponent has been mostly cooperative and we're not in an endgame.
    if last_op == 'D':
        # Ignore very rare defections (noise-like) but don't be a total sucker.
        if opp_rate > 0.8 and streak_len == 1 and rounds_left > 8:
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        if opp_rate > 0.65 and recent_opp_d <= 2:
            # One-time forgiveness to avoid DD spirals.
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        if recent_my_d >= 4 and recent_opp_d <= 2:
            return 'C'
        return 'D'

    # Opponent cooperated. Reward them, with occasional controlled probing.
    # Avoid probing too much against mixed opponents.
    if opp_rate >= 0.6:
        if rounds_left > 12 and n > 6 and recent_my_d == 0:
            if rng.random() < 0.06:
                return 'D'
        return 'C'

    # Mixed opponent, last round C: cautious cooperation.
    if opp_rate >= 0.35:
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    # Low-ish cooperation but not hopeless: default cooperate only if they
    # just cooperated; otherwise defect.
    if last_op == 'C' and rng.random() < 0.5:
        return 'C'
    return 'D'
